/bin/bash -c "python - <<'PY'
from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png'))
# table background estimated row median from x=75:102
for y in range(16,45):
 row=[]
 for x in range(100,128):
  p=im[y,x].astype(int)
  bg=np.median(im[y,75:102],axis=0).astype(int)
  d=np.linalg.norm(p-bg)
  if d>35: row.append('#')
  elif d>18: row.append('+')
  else: row.append('.')
 print(f'{y:2}', ''.join(row))
PY"
